"use client";

/** Private data binding for the approved AppShell presentation.
 * The class names, hierarchy and component families below are recovered from
 * bb210869 AppShell. No demo dataset or v1 endpoint is used by this branch.
 */
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { useCallback, useEffect, useState } from "react";
import { AlertTriangle, CalendarClock, CheckCircle2, ChevronRight, ClipboardCheck, Clock3, Database, Droplets, Filter, Gauge, HelpCircle, PackageSearch, Printer, Search, ShieldCheck, Sparkles, Target, TrendingDown, Wrench } from "lucide-react";
import type { PrivateSession } from "@/lib/private-auth";
import type { readOperation } from "@/lib/operational-store";
import type { OperationalShift, OperationalReport } from "@/packages/import/types";
import { compareCrownHistory, reconstructCrownHistory } from "@/packages/domain/crown-history";
import { EChart } from "./echart";
import { RecoveredDecisionPanel, RecoveredDecisionEvidence, RecoveredImportPanel, RecoveredAssistant as PrivateAssistant, CostHypothesis } from "./recovered-controls";
import { PrivateRecordActions } from "./private-record-actions";

export type RecoveredData=Awaited<ReturnType<typeof readOperation>>;
type ViewProps={data:RecoveredData;session:PrivateSession;reload:()=>Promise<void>};
const fmt=(n:number|null|undefined,d=1)=>typeof n==="number"&&Number.isFinite(n)?new Intl.NumberFormat("es-EC",{maximumFractionDigits:d}).format(n):"—";
const sumKnown=(values:(number|null|undefined)[])=>values.some(v=>typeof v==="number"&&Number.isFinite(v))?values.reduce<number>((sum,v)=>sum+(typeof v==="number"&&Number.isFinite(v)?v:0),0):null;
const ratio=(a:number|null,b:number|null)=>a!==null&&b!==null&&b>0?a/b:null;
const colors=["#f5f7fa","#2389ba","#41d6a3","#bd8cff","#ff9f43","#f4b942","#ff6969"];
const contextHref=(data:RecoveredData,path:string,extra:Record<string,string>={})=>`${path}?${new URLSearchParams({...data.filters,...extra})}`;
function Pagination({page,total,size,onPage}:{page:number;total:number;size:number;onPage:(page:number)=>void}){const count=Math.max(1,Math.ceil(total/size));return <div className="pagination"><span>Mostrando {total?1+(page-1)*size:0}–{Math.min(page*size,total)} de {total} registros</span><button disabled={page===1} onClick={()=>onPage(page-1)}>Anterior</button>{Array.from({length:count},(_,i)=>i+1).filter(n=>n===1||n===count||Math.abs(n-page)<=2).map(n=><button key={n} className={n===page?"active":""} onClick={()=>onPage(n)}>{n}</button>)}<button disabled={page===count} onClick={()=>onPage(page+1)}>Siguiente</button></div>}
function Head({title,subtitle,actionHref,action}:{title:string;subtitle?:string;actionHref?:string;action?:string}){return <header className="panel-head"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div>{actionHref&&<Link href={actionHref}>{action}<ChevronRight/></Link>}</header>}
function Kpi({label,value,unit,icon:Icon=Gauge,tone="green",sub}:{label:string;value:string;unit?:string;icon?:typeof Gauge;tone?:string;sub?:string}){return <div className="kpi-card"><div className={`kpi-icon ${tone}`}><Icon/></div><div className="kpi-label">{label}<span title={sub}><HelpCircle/></span></div><div className="kpi-value">{value}<small>{unit}</small></div>{sub&&<div className="kpi-sub">{sub}</div>}</div>}
function Pending({children}:{children:React.ReactNode}){return <div className="source-note" style={{padding:20}}><AlertTriangle/><div><b>Dato pendiente</b><p>{children}</p></div></div>}
function Range({label,unit,values,tone}:{label:string;unit:string;values:(number|null)[];tone:string}){const clean=values.filter((x):x is number=>x!==null&&Number.isFinite(x));return <div className="metric-range"><header><i style={{background:tone}}/><span>{label}</span><b>{fmt(clean.length?clean.reduce((a,b)=>a+b,0)/clean.length:null)} {unit}</b></header><div>{[["MÍN.",clean.length?Math.min(...clean):null],["PROM.",clean.length?clean.reduce((a,b)=>a+b,0)/clean.length:null],["MÁX.",clean.length?Math.max(...clean):null]].map(([name,value])=><span key={name}><small>{name}</small>{fmt(value as number|null)}</span>)}</div><small>{clean.length} de {values.length} lecturas de turno</small></div>}
function cartesian(labels:string[],series:{name:string;values:(number|null)[];color:string;type?:string}[],unit="m"){return {tooltip:{trigger:"axis"},legend:{top:4,textStyle:{color:"#89949d"}},grid:{left:55,right:24,top:44,bottom:50},xAxis:{type:"category",data:labels,axisLabel:{color:"#7f8c94",hideOverlap:true},axisLine:{lineStyle:{color:"#2a3339"}}},yAxis:{type:"value",name:unit,axisLabel:{color:"#7f8c94"},splitLine:{lineStyle:{color:"#20292f"}}},series:series.map(s=>({name:s.name,type:s.type??"bar",data:s.values,itemStyle:{color:s.color},lineStyle:{color:s.color},barMaxWidth:24,connectNulls:false}))};}
function activities(shifts:OperationalShift[]){const groups=new Map<string,number>();for(const s of shifts)for(const a of s.activities)if(a.hours!==null&&a.hours>=0)groups.set(a.label,(groups.get(a.label)??0)+a.hours);return [...groups].sort((a,b)=>b[1]-a[1]);}
function daySeries(shifts:OperationalShift[]){const dates=[...new Set(shifts.map(s=>s.date))].sort();return {dates,series:(["day","night"] as const).map((type,i)=>({name:i?"Noche":"Día",color:colors[i],values:dates.map(date=>sumKnown(shifts.filter(s=>s.date===date&&s.shiftType===type).map(s=>s.advanceM)))}))};}
function Activities({shifts,horizontal=false}:{shifts:OperationalShift[];horizontal?:boolean}){const rows=activities(shifts);const option=horizontal?{tooltip:{trigger:"axis"},grid:{left:140,right:20,top:18,bottom:28},xAxis:{type:"value",axisLabel:{color:"#71808a",formatter:"{value} h"},splitLine:{lineStyle:{color:"#20292f"}}},yAxis:{type:"category",data:rows.map(r=>r[0]).reverse(),axisLabel:{color:"#a6b0b7",interval:0,fontSize:9,width:125,overflow:"truncate"},axisLine:{show:false}},series:[{type:"bar",data:rows.map(r=>r[1]).reverse(),barWidth:8,itemStyle:{color:(p:{dataIndex:number})=>colors[p.dataIndex%colors.length],borderRadius:[0,4,4,0]}}]}:{tooltip:{trigger:"item"},legend:{type:"scroll",bottom:0,textStyle:{color:"#89949d"}},series:[{type:"pie",radius:["30%","65%"],data:rows.map(([name,value],i)=>({name,value,itemStyle:{color:colors[i%colors.length]}}))}]};return <section className="panel"><Head title={horizontal?"Pareto de horas por actividad":"Horas por actividad"} subtitle="Reparto agregado observado; no es un Gantt ni una clasificación automática de NPT"/><EChart className={horizontal?"chart chart-lg":"chart"} ariaLabel="Horas observadas por actividad" option={option}/></section>}
function Parameters({shifts}:{shifts:OperationalShift[]}){return <section className="panel parameters-panel"><Head title="Parámetros de perforación" subtitle="Observaciones por turno · no telemetría ni intervalos interpolados"/><div className="parameters-grid"><Range label="RPM" unit="rpm" values={shifts.map(s=>s.parameters.rpm)} tone="#bd8cff"/><Range label="Pulldown" unit="PSI" values={shifts.map(s=>s.parameters.pulldownPsi)} tone="#56c7ff"/><Range label="Holdback" unit="PSI" values={shifts.map(s=>s.parameters.holdbackPsi)} tone="#41d6a3"/><Range label="Torque" unit="unidad sin confirmar" values={shifts.map(s=>s.parameters.torque)} tone="#ff9f43"/></div></section>}
function ShiftEvidence({shifts}:{shifts:RecoveredData["shifts"]}){return <details className="panel" style={{padding:18}}><summary>Detalle de origen y fiscalización · {shifts.length} posiciones de turno</summary><div style={{overflowX:"auto"}}><table><thead><tr><th>Fecha / guardia</th><th>Equipo / sondeo</th><th>Desde / hasta m</th><th>Avance m</th><th>Perforación h</th><th>Archivo / hoja</th><th>Incidencias</th></tr></thead><tbody>{shifts.map(s=><tr key={s.logicalKey}><td>{s.date} · {s.shiftType==="day"?"Día":"Noche"}</td><td>{s.rigCode} · {s.holeCode??"No registrado"}</td><td>{fmt(s.startDepthM)} / {fmt(s.endDepthM)}</td><td>{fmt(s.advanceM)}</td><td>{fmt(s.drillingHours)}</td><td>{s.source.file}<br/>{s.source.sheet} · rev. {s.revision}</td><td>{s.warnings.join(", ")||"Sin incidencias registradas"}</td></tr>)}</tbody></table></div></details>}

export function RecoveredOperationalViews({section,session,initialData}:{section:string;session:PrivateSession;initialData?:RecoveredData}){
 const search=useSearchParams();
 const [data,setData]=useState(initialData),[error,setError]=useState("");
 const [from,setFrom]=useState(search.get("from")??initialData?.filters.from??""),[to,setTo]=useState(search.get("to")??initialData?.filters.to??""),[rig,setRig]=useState(search.get("rig")??initialData?.filters.rig??""),[hole,setHole]=useState(search.get("hole")??initialData?.filters.hole??"");
 const query=new URLSearchParams({from,to,rig,hole}).toString();
 function changeFilter(key:"from"|"to"|"rig"|"hole",value:string){
  ({from:setFrom,to:setTo,rig:setRig,hole:setHole})[key](value);
  const next=new URLSearchParams({from,to,rig,hole,[key]:value});
  window.history.replaceState(null,"",`${window.location.pathname}?${next}`);
 }
 const reload=useCallback(async()=>{try{const r=await fetch(`/api/v2/operation?${query}`,{cache:"no-store"});const body=await r.json();if(!r.ok)throw Error(body.error??"No se pudo leer la operación");setData(body);setError("");}catch(e){setData(undefined);setError(e instanceof Error?e.message:"Servicio no disponible");}},[query]);
 useEffect(()=>{const controller=new AbortController();fetch(`/api/v2/operation?${query}`,{cache:"no-store",signal:controller.signal}).then(async r=>{const body=await r.json();if(!r.ok)throw Error(body.error??"No se pudo leer la operación");return body as RecoveredData}).then(body=>{setData(body);setError("");}).catch(e=>{if(!controller.signal.aborted){setData(undefined);setError(e.message);}});return()=>controller.abort();},[query]);
 const props=data?{data,session,reload}:null;
return <><div className="filterbar"><div><Filter size={15}/>Filtros</div><label>Desde<input type="date" aria-label="Desde" value={from} onChange={e=>changeFilter("from",e.target.value)}/></label><label>Hasta<input type="date" aria-label="Hasta" value={to} onChange={e=>changeFilter("to",e.target.value)}/></label><label>Sondeo<select value={hole} aria-label="Sondeo" onChange={e=>changeFilter("hole",e.target.value)}><option value="">Todos los sondeos</option>{data?.availableHoles.map(h=><option key={h}>{h}</option>)}</select></label><label>Taladro<select value={rig} aria-label="Equipo" onChange={e=>changeFilter("rig",e.target.value)}><option value="">Todos los equipos</option>{data?.availableRigs.map(r=><option key={r}>{r}</option>)}</select></label><button onClick={()=>{setFrom("");setTo("");setRig("");setHole("");window.history.replaceState(null,"",window.location.pathname);}}>Limpiar</button></div>
 {error&&<p className="form-error" role="alert">{error}. No se sustituyen los registros por una demo. <button onClick={()=>void reload()}>Reintentar</button></p>}
 {!data&&!error&&<p role="status">Cargando el contexto autorizado…</p>}
 {props&&<>
 {["operacion","turnos","intervalos","coronas","consumibles","survey","reportes"].includes(section)&&<PrivateRecordActions section={section} session={session} filters={data!.filters} onSaved={()=>void reload()}/>}
 {section==="dashboard"&&<RecoveredDashboard {...props}/>}
 {section==="dashboard"&&<ConsumptionSummary data={data!}/>}
 {section==="dashboard"&&<DiameterSummary data={data!}/>}
 {section==="operacion"&&<RecoveredOperation {...props}/>}
 {section==="operacion"&&<ReportObservations data={data!} kind="equipmentHours"/>}
 {section==="turnos"&&<RecoveredShifts {...props}/>}
 {section==="sondeos"&&<RecoveredHoles {...props}/>}
 {section==="taladros"&&<RecoveredRigs {...props}/>}
 {section==="taladros"&&<CostHypothesis session={session}/>}
 {section==="intervalos"&&<RecoveredIntervals {...props}/>}
 {section==="coronas"&&<RecoveredCrowns {...props}/>}
 {section==="bit-advisor"&&<RecoveredAdvisor {...props}/>}
 {section==="depth-intelligence"&&<RecoveredDepth {...props}/>}
 {section==="survey"&&<RecoveredSurvey {...props}/>}
 {section==="inventario"&&<RecoveredInventory {...props}/>}
 {section==="consumibles"&&<RecoveredConsumables {...props}/>}
 {section==="consumibles"&&<CostHypothesis session={session}/>}
 {section==="consumibles"&&<ReportObservations data={data!} kind="fluidParameters"/>}
 {section==="analitica"&&<RecoveredAnalytics {...props}/>}
 {section==="importaciones"&&<RecoveredImports {...props}/>}
 {section==="drill-assistant"&&<RecoveredAssistant {...props}/>}
 {section==="reportes"&&<RecoveredReport {...props}/>}
 {section==="reportes"&&<DiameterSummary data={data!}/>}
 {section==="configuracion"&&<RecoveredSettings {...props}/>}
 </>}
 </>;
}

function RecoveredDashboard({data}:ViewProps){
 const {shifts,summary}=data, daily=daySeries(shifts),pairedHours=shifts.filter(s=>s.totalHours!==null&&s.drillingHours!==null),hours=sumKnown(pairedHours.map(s=>s.totalHours)),util=ratio(sumKnown(pairedHours.map(s=>s.drillingHours)),hours),depths=shifts.map(s=>s.endDepthM).filter((n):n is number=>n!==null);
 const history=reconstructCrownHistory(data.crowns,shifts),last=history.runs.at(-1);
 const cumulativeValues=daily.dates.map(date=>sumKnown(shifts.filter(s=>s.date===date).map(s=>s.advanceM))===null?null:sumKnown(shifts.filter(s=>s.date<=date).map(s=>s.advanceM)));
 const issues=shifts.filter(s=>s.warnings.length);
 return <><div className="demo-banner"><ShieldCheck/><div><b>Contexto operacional privado · datos observados</b><span>{summary.shiftCount} posiciones de turno · {summary.missingAdvance} avances y {summary.missingHours} horas no registrados. Ausencia no equivale a cero.</span></div><Link href={contextHref(data,"/depth-intelligence")}>Explorar profundidad <ChevronRight/></Link></div>
 <section className="kpi-grid"><Kpi label="Metros perforados" value={fmt(summary.advanceM)} unit="m" icon={Target} sub="Suma de avances conocidos; excluye casing"/><Kpi label="ROP ponderado" value={fmt(summary.ropMPerHour,3)} unit="m/h" icon={Gauge} tone="blue" sub={`${summary.ropCoverage} turnos con metros y horas pareados`}/><Kpi label="Utilización observada" value={fmt(util===null?null:util*100)} unit="%" icon={Clock3} tone="amber" sub="Horas de perforación / horas registradas; no disponibilidad mecánica"/><Kpi label="Cumplimiento del plan" value="—" icon={Target} tone="purple" sub="Requiere meta declarada; no se infiere del avance"/><Kpi label="Profundidad observada" value={fmt(depths.length&&summary.holes.length===1?Math.max(...depths):null)} unit="m" icon={TrendingDown} tone="cyan" sub="Selecciona un sondeo; no se suman profundidades"/></section>
 <div className="planning-grid"><section className="panel"><Head title="Avance ejecutado vs programado" subtitle="Ejecutado acumulado · programación pendiente de meta declarada"/><EChart option={cartesian(daily.dates,[{name:"Ejecutado acumulado",values:cumulativeValues,color:"#2389ba"},{name:"Programado acumulado",values:daily.dates.map(()=>null),color:"#d7ff43",type:"line"}])} className="chart chart-lg" ariaLabel="Avance acumulado observado, meta no registrada"/></section><section className="panel availability-panel"><Head title="Disponibilidad mecánica" subtitle="Se conserva el panel; requiere clasificación aprobada de mantenimiento y averías"/><EChart className="chart chart-lg" ariaLabel="Disponibilidad mecánica pendiente de clasificación" option={{series:[{type:"gauge",startAngle:205,endAngle:-25,min:0,max:100,axisLine:{lineStyle:{width:15,color:[[1,"#29353c"]]}},pointer:{show:false},axisLabel:{color:"#718087"},detail:{formatter:"Pendiente",fontSize:22,color:"#edf2f4"},data:[{value:null}]}]}}/></section></div>
 <Parameters shifts={shifts}/>
 <div className="dashboard-grid"><section className="panel span-2"><Head title="Rendimiento por guardia y máquina" subtitle="Día blanco · noche azul · filtros compartidos"/><EChart option={cartesian(daily.dates,daily.series)} className="chart chart-lg" ariaLabel="Metros observados día y noche"/></section><section className="panel progress-panel"><Head title="Avance del sondeo" subtitle={summary.holes.length===1?(summary.holes[0]??"Sondeo no registrado"):"Selecciona un sondeo"}/><div className="depth-gauge"><div><span style={{height:0}}/></div><section><b>{fmt(summary.holes.length===1&&depths.length?Math.max(...depths):null)} m</b><p>profundidad observada</p><dl><dt>Objetivo</dt><dd>No registrado</dd><dt>Restante</dt><dd>Requiere objetivo</dd><dt>Meta diaria</dt><dd>No registrada</dd></dl></section></div><div className="eta-box"><CalendarClock/><div><small>FINALIZACIÓN ESTIMADA</small><b>Pendiente de objetivo</b><span>No extrapolamos una fecha contractual.</span></div></div></section>
 <Activities shifts={shifts} horizontal/><section className="panel crown-focus"><Head actionHref={contextHref(data,"/coronas")} action="Ver rendimiento" title="Corona de historial reciente" subtitle={last?`${last.serial??"Serie no informada"} · ${last.type??"Tipo no informado"}`:"Sin observación"}/>{last?<div className="crown-health"><div className="ring" style={{background:"radial-gradient(circle,#151f25 56%,transparent 58%),#29353c",boxShadow:"none"}}><b>—</b><small>desgaste no medido</small></div><div><dl><dt>Metros atribuibles</dt><dd>{fmt(last.attributedMetresM)} m</dd><dt>ROP atribuible</dt><dd>{fmt(last.ropMPerHour)} m/h</dd><dt>Stock</dt><dd>No confirmado</dd></dl></div></div>:<Pending>No hay instantáneas de coronas para el filtro.</Pending>}</section></div>
 <section className="panel alert-panel"><Head title="Alertas operacionales" subtitle={`${issues.length} posiciones con incidencias de fuente · no se inventan anomalías`}/><div className="alert-list">{issues.slice(0,5).map(s=><div className="warning" key={s.logicalKey}><AlertTriangle/><div><b>{s.rigCode} · {s.date}</b><span>{s.warnings.join(" · ")}</span></div><small>{s.shiftType==="day"?"Día":"Noche"}</small><Link href={contextHref(data,"/turnos")}>Revisar</Link></div>)}</div></section></>;
}

function RecoveredOperation({data}:ViewProps){const last=data.shifts.at(-1);return <><div className="operation-live"><span><i/>ÚLTIMO TURNO REGISTRADO</span><h2>{last?.holeCode??"Sondeo no informado"} · {last?.rigCode??"Sin equipo"}</h2><p>Personal no incorporado a la vista · datos de fuente desidentificados</p><time>{last?.date??"Sin fecha"} · {last?.shiftType==="day"?"Día":"Noche"}</time></div><div className="kpi-grid four"><Kpi label="Avance del turno" value={fmt(last?.advanceM)} unit="m" icon={Target}/><Kpi label="ROP del turno" value={fmt(ratio(last?.advanceM??null,last?.drillingHours??null),2)} unit="m/h" tone="blue"/><Kpi label="Horas efectivas" value={fmt(last?.drillingHours)} unit="h" icon={Clock3} tone="amber"/><Kpi label="Rango de turno" value={`${fmt(last?.startDepthM)} – ${fmt(last?.endDepthM)}`} unit="m" icon={Database} tone="purple"/></div><section className="panel"><Head title="Registro rápido del turno" subtitle="Acciones del contexto operacional"/><div className="quick-links">{[["turnos","Turnos",Clock3],["coronas","Cambio de corona",PackageSearch],["consumibles","Consumos",Droplets],["survey","Survey",TrendingDown]].map(([route,title,Icon])=>{const I=Icon as typeof Gauge;return <Link key={String(route)} href={contextHref(data,`/${route}`)}><I/><b>{String(title)}</b><span>Consultar y capturar según permisos</span></Link>})}</div></section><div className="split-grid"><Activities shifts={data.shifts}/><section className="panel"><Head title="Horas de perforación por guardia" subtitle="Horas efectivas; no horómetro acumulado"/><EChart option={cartesian(data.shifts.map(s=>`${s.date} ${s.shiftType==="day"?"D":"N"}`),[{name:"PERFORACIÓN",values:data.shifts.map(s=>s.drillingHours),color:"#41d6a3"}],"h")}/></section></div><Parameters shifts={data.shifts}/><ShiftEvidence shifts={data.shifts}/></>}
function RecoveredShifts({data}:ViewProps){const [selected,setSelected]=useState<string|null>(null),[page,setPage]=useState(1);const currentPage=Math.min(page,Math.max(1,Math.ceil(data.shifts.length/24)));return <><section className="panel table-panel"><table><thead><tr><th>Fecha</th><th>Turno</th><th>Sondeo</th><th>Taladro</th><th>Avance</th><th>Perforación</th><th>Horas registradas</th><th>Validación 12 h</th><th>Detalle</th></tr></thead><tbody>{data.shifts.slice((currentPage-1)*24,currentPage*24).map(s=><tr key={s.logicalKey}><td>{s.date}</td><td><span className={`tag ${s.shiftType==="day"?"":"blue"}`}>{s.shiftType==="day"?"☀ Día":"☾ Noche"}</span></td><td>{s.holeCode??"No registrado"}</td><td>{s.rigCode}</td><td>{fmt(s.advanceM)} m</td><td>{fmt(s.drillingHours)} h</td><td>{fmt(s.totalHours)} h</td><td><span className={`status ${s.totalHours===12?"success":"warning"}`}>{s.totalHours===12?"COMPLETO":s.totalHours===null?"SIN DATO":"REVISAR"}</span></td><td><button onClick={()=>setSelected(selected===s.logicalKey?null:s.logicalKey)}>Actividades</button></td></tr>)}</tbody></table><Pagination page={currentPage} total={data.shifts.length} size={24} onPage={setPage}/></section>{selected&&<Activities shifts={data.shifts.filter(s=>s.logicalKey===selected)}/>}<ShiftEvidence shifts={data.shifts}/></>}
function RecoveredHoles({data}:ViewProps){const [query,setQuery]=useState("");return <><div className="actionbar"><div className="search"><Search/><input aria-label="Buscar sondeos" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar sondeo…"/></div><span className="status">Estado contractual no registrado</span></div><div className="cards-grid">{data.summary.holes.filter(h=>h?.toLowerCase().includes(query.toLowerCase())).map(h=>{const rows=data.shifts.filter(s=>s.holeCode===h),depths=rows.map(s=>s.endDepthM).filter((x):x is number=>x!==null);return <article className="hole-card" key={h}><header><div><span className="status success">OBSERVADO EN REPORTES</span><h3>{h}</h3><p>{[...new Set(rows.map(s=>s.projectCode).filter(Boolean))].join(" · ")||"Proyecto no registrado"}</p></div><Target/></header><div className="hole-depth"><div/><b>{fmt(depths.length?Math.max(...depths):null)} m</b><small> / objetivo no registrado</small></div><dl><dt>Diámetro declarado</dt><dd>{[...new Set(rows.map(s=>s.diameter).filter(Boolean))].join(", ")||"No registrado"}</dd><dt>Taladro</dt><dd>{[...new Set(rows.map(s=>s.rigCode))].join(", ")}</dd><dt>Avance observado</dt><dd>{fmt(sumKnown(rows.map(s=>s.advanceM)))} m</dd><dt>Meta diaria</dt><dd>No registrada</dd><dt>Primera observación</dt><dd>{rows[0]?.date}</dd><dt>ETA</dt><dd>Requiere objetivo</dd></dl><footer><Link style={{display:"inline-flex",alignItems:"center",justifyContent:"space-between",width:"100%"}} href={contextHref(data,"/depth-intelligence",{hole:h!})}>Ver inteligencia del sondeo <ChevronRight/></Link></footer></article>})}</div></>}
function RecoveredRigs({data}:ViewProps){const [selected,setSelected]=useState<string|null>(null);return <><div className="cards-grid rigs-grid">{data.summary.rigs.map(code=>{const rows=data.shifts.filter(s=>s.rigCode===code);return <article className="rig-card" key={code}><header><div className="rig-icon"><Wrench/></div><div><span className="status success">OBSERVADO</span><h3>{code}</h3><p>Fabricante / modelo no registrados</p></div></header><dl><dt>Serie</dt><dd>No registrada</dd><dt>Avance</dt><dd>{fmt(sumKnown(rows.map(s=>s.advanceM)))} m</dd><dt>Horas perforación</dt><dd>{fmt(sumKnown(rows.map(s=>s.drillingHours)))} h</dd><dt>Horómetro acumulado</dt><dd>No registrado</dd><dt>Fuente</dt><dd>Reporte operacional</dd></dl><div className="capabilities"><small>PARÁMETROS OBSERVADOS</small>{(["rpm","torque","pulldownPsi","holdbackPsi"] as const).map(k=><span key={k} className={rows.some(s=>s.parameters[k]!==null)?"on":""}>{k}</span>)}</div><button onClick={()=>setSelected(selected===code?null:code)}>Ver ficha del equipo <ChevronRight/></button></article>})}</div>{selected&&<><Parameters shifts={data.shifts.filter(s=>s.rigCode===selected)}/><ShiftEvidence shifts={data.shifts.filter(s=>s.rigCode===selected)}/></>}<section className="panel supplementary-panel"><Head title="Economía del equipo" subtitle="Se conserva el bloque; requiere tarifa declarada de esta campaña"/><Pending>Sin tarifa autorizada no calculamos USD/h ni USD/m. Las tarifas históricas de otras campañas no se reutilizan.</Pending></section></>}
function RecoveredIntervals({data}:ViewProps){const [page,setPage]=useState(1);const currentPage=Math.min(page,Math.max(1,Math.ceil(data.shifts.length/18)));return <><div className="actionbar"><Database/><span>Granularidad disponible: turno · intervalos de 3 / 1,5 m no inferidos</span></div><section className="panel table-panel"><table><thead><tr><th>Desde / hasta</th><th>Sondeo / turno</th><th>ROP agregada</th><th>RPM</th><th>Torque</th><th>Orientación declarada</th><th>MSE</th><th>Litología / Mohs</th><th>Recup.</th><th>Fuente</th><th>Condición</th></tr></thead><tbody>{data.shifts.slice((currentPage-1)*18,currentPage*18).map(s=><tr key={s.logicalKey}><td>{fmt(s.startDepthM)} – {fmt(s.endDepthM)} m</td><td>{s.holeCode} · {s.date} {s.shiftType==="day"?"Día":"Noche"}</td><td>{fmt(ratio(s.advanceM,s.drillingHours),2)} m/h</td><td>{fmt(s.parameters.rpm)}</td><td>{fmt(s.parameters.torque)} · unidad pendiente</td><td>{fmt(s.observedDip,2)}° / {fmt(s.observedAzimuth,2)}°<small className="block">DIP / azimut del reporte</small></td><td>—<small className="block">Fuerza / unidad / geometría pendientes</small></td><td>No declarada</td><td>—</td><td><span className="source">TURNO IMPORTADO</span></td><td>No registrada</td></tr>)}</tbody></table><Pagination page={currentPage} total={data.shifts.length} size={18} onPage={setPage}/></section><Pending>Estos rangos no son mediciones de recuperación, dureza o litología. La captura de intervalos medidos debe distinguirse del histórico por turno.</Pending></>}

function CrownEvidence({data}:{data:RecoveredData}){const history=reconstructCrownHistory(data.crowns,data.shifts);return <details className="panel table-panel"><summary style={{padding:18}}>Historial y evidencia · {history.runs.length} corridas identificadas o provisionales · {history.duplicateSnapshots} instantáneas repetidas no sumadas</summary><div style={{overflowX:"auto"}}><table><thead><tr><th>Serie / tipo</th><th>Equipo / sondeo</th><th>Desde / hasta m</th><th>Reportado m</th><th>Atribuible m</th><th>ROP m/h</th><th>Evidencia</th></tr></thead><tbody>{history.runs.map(r=><tr key={r.id}><td>{r.serial??"Identidad incompleta"}<br/>{r.type??"Tipo no registrado"}</td><td>{r.rigCode} · {r.holeCode}</td><td>{fmt(r.startDepthM)} / {fmt(r.endDepthM)}</td><td>{fmt(r.reportedMetresM)}</td><td>{fmt(r.attributedMetresM)}</td><td>{fmt(r.ropMPerHour,3)}</td><td>{r.shiftKeys.length} turnos atribuibles<details><summary>Límites de atribución</summary>{r.reasons.join(" · ")}</details></td></tr>)}</tbody></table></div><p style={{padding:18}}>{history.uncertainShiftCount} turnos sin atribución segura. Los metros reportados son el máximo observado, no la suma de instantáneas. Un final informado no demuestra retiro o vida útil.</p></details>}
function RecoveredCrowns({data}:ViewProps){const [showAll,setShowAll]=useState(false);const history=reconstructCrownHistory(data.crowns,data.shifts),comparison=compareCrownHistory(history);return <><div className="kpi-grid four"><Kpi label="Corridas observadas" value={String(history.runs.length)} icon={PackageSearch} sub="Identificadas o provisionales; no conteo de compras"/><Kpi label="Metros atribuibles" value={fmt(history.runs.reduce((s,r)=>s+r.attributedMetresM,0))} unit="m" tone="blue" sub="Una sola corona cubre todo el rango del turno"/><Kpi label="Vida útil" value="—" icon={ShieldCheck} tone="amber" sub="No inferida de instantáneas ni de caída de ROP"/><Kpi label="Turnos sin atribución" value={String(history.uncertainShiftCount)} icon={AlertTriangle} tone="purple"/></div><div className="split-grid"><section className="panel"><Head title="Velocidad vs metros atribuibles" subtitle="Comparación descriptiva; metros no equivalen a vida útil"/><EChart className="chart chart-lg" ariaLabel="Comparación de ROP y metros atribuibles por marca y tipo" option={{tooltip:{trigger:"item"},grid:{left:65,right:25,top:35,bottom:55},xAxis:{type:"value",name:"ROP m/h",axisLabel:{color:"#89949d"}},yAxis:{type:"value",name:"Metros atribuibles",axisLabel:{color:"#89949d"}},series:[{type:"scatter",symbolSize:26,data:comparison.filter(r=>r.ropMPerHour!==null).map(r=>({name:`${r.brand??"Marca no informada"} ${r.type??"Tipo no informado"}`,value:[r.ropMPerHour,r.attributedMetresM]})),itemStyle:{color:"#56c7ff"},label:{show:true,position:"top",formatter:"{b}",color:"#d9e0e4"}}]}}/></section><section className="panel"><Head title="Comparación transparente" subtitle="ROP pareada de turnos atribuibles; no ranking comercial"/><div className="crown-ranking">{comparison.slice(0,showAll?undefined:5).map(r=><div key={`${r.brand}|${r.type}`}><span>◈</span><div><b>{r.brand??"Marca no informada"}</b><small>{r.type??"Tipo no informado"} · {r.runCount} corridas</small></div><dl><dt>ROP</dt><dd>{fmt(r.ropMPerHour,3)} m/h</dd><dt>Atribuibles</dt><dd>{fmt(r.attributedMetresM)} m</dd><dt>Stock</dt><dd>No confirmado</dd></dl></div>)}</div>{comparison.length>5&&<button className="button-link" onClick={()=>setShowAll(!showAll)}>{showAll?"Ver cinco comparaciones":`Ver las ${comparison.length} comparaciones observadas`}</button>}</section></div><CrownEvidence data={data}/><section className="panel supplementary-panel"><Head title="MSE y geología" subtitle="Cálculo físico separado de litología o dureza declaradas"/><Pending>Faltan fuerza axial válida, torque con unidad confirmada y geometría exterior/interior. PSI no equivale a WOB; HQ (63,5 mm) no confirma el diámetro exterior de la corona.</Pending></section></>}
function RecoveredAdvisor({data,session,reload}:ViewProps){const history=reconstructCrownHistory(data.crowns,data.shifts),comparison=compareCrownHistory(history);const eligible=history.runs.filter(r=>r.ropMPerHour!==null&&r.shiftKeys.length>=2&&r.type&&r.serial&&r.holeCode);const sameContext=new Set(history.runs.map(r=>r.rigCode)).size===1&&new Set(history.runs.map(r=>r.holeCode)).size===1&&history.runs.every(r=>r.holeCode);const candidate=sameContext&&eligible.length>0&&new Set(eligible.map(r=>r.type)).size===1?[...eligible].sort((a,b)=>(b.ropMPerHour??0)-(a.ropMPerHour??0))[0]:undefined;const [method,setMethod]=useState(false),[showAll,setShowAll]=useState(false);return <><div className="advisor-layout"><section className="panel advisor-form"><div className="advisor-step"><i>1</i><div><h3>Contexto operacional</h3><p>Historial del filtro superior.</p></div></div><label>Sondeo<input readOnly value={data.summary.holes.join(", ")||"Sin sondeo declarado"}/></label><label>Taladro<input readOnly value={data.summary.rigs.join(", ")}/></label><label>Tipos de corona observados<input readOnly value={[...new Set(history.runs.map(r=>r.type).filter(Boolean))].join(", ")||"No registrados"}/></label><hr/><div className="advisor-step"><i>2</i><div><h3>Condición y evidencia</h3><p>No se infiere la formación de la ROP.</p></div></div><div className="advisor-evidence"><span><small>MSE física</small><b>Pendiente</b></span><span><small>UCS independiente</small><b>No registrada</b></span><span><small>Litología</small><b>No declarada</b></span></div><Pending>Para MSE se requiere fuerza, torque con unidades y geometría. El factor de fricción solicitado aún no tiene contrato físico validado.</Pending><hr/><div className="advisor-step"><i>3</i><div><h3>Prioridad de revisión</h3><p>Comparación histórica, no recomendación causal.</p></div></div><div className="priority-grid"><button className="active" type="button"><Gauge/><b>ROP observada</b><small>Con cobertura atribuible</small></button><button disabled><ShieldCheck/><b>Vida / desgaste</b><small>No medidos</small></button></div></section><section className="advisor-results"><div className="advisor-result-head"><div><span className="demo-pill"><i/>MOTOR DETERMINÍSTICO</span><h2>{candidate?`Candidato para revisión: ${candidate.serial}`:"Mantener revisión manual"}</h2><p>{candidate?"Mayor ROP observada entre corridas elegibles del mismo equipo, sondeo y tipo.":"Requiere único equipo/sondeo, tipo común y dos turnos atribuibles por candidato."}</p></div><button onClick={()=>setMethod(!method)} aria-expanded={method}><HelpCircle/>Cómo se calcula</button></div>{method&&<div className="method-note"><ShieldCheck/><div><b>historical-review-v1 · preservado</b><p>No se calcula puntuación comercial, desgaste ni vida restante. El supervisor debe confirmar régimen, geología, compatibilidad y stock antes de considerar una instalación. El candidato no demuestra superioridad causal.</p></div></div>}{comparison.slice(0,showAll?undefined:3).map(r=><article key={`${r.brand}|${r.type}`} className="recommend-card"><div className="rank"><small>HISTORIAL</small><b>◈</b><span>{r.runCount}<small>corridas</small></span></div><div className="rec-main"><div className="crown-title"><div className="crown-icon">◈</div><div><small>{r.brand??"Marca no informada"}</small><h3>{r.type??"Tipo no informado"}</h3><span>Comparación observada, sin puntaje</span></div><div className="confidence low">Régimen sin confirmar</div></div><div className="rec-metrics"><div><small>ROP atribuible</small><b>{fmt(r.ropMPerHour,3)} <i>m/h</i></b></div><div><small>Metros atribuibles</small><b>{fmt(r.attributedMetresM)} <i>m</i></b></div><div><small>Turnos</small><b>{r.attributedShiftCount}</b></div><div><small>Stock / costo</small><b>—</b></div></div><div className="rec-reasons"><b>Por qué aparece aquí</b><span><CheckCircle2/>Marca/tipo observados en el contexto</span><span><CheckCircle2/>ROP ponderada sólo con atribución y horas válidas</span></div><div className="low-confidence"><AlertTriangle/>No confundir metros reportados con vida útil ni disponibilidad.</div></div></article>)}{comparison.length>3&&<button className="button-link" onClick={()=>setShowAll(!showAll)}>{showAll?"Ver tres comparaciones":`Ver las ${comparison.length} comparaciones observadas`}</button>}{comparison.length===0&&<Pending>No hay historial de coronas en el filtro. No se añade catálogo demo.</Pending>}</section></div><RecoveredDecisionPanel session={session} data={data} filters={data.filters} onReload={reload}/><CrownEvidence data={data}/><section className="panel supplementary-panel bha-readiness"><Head title="Próxima fase · circulación y BHA" subtitle="Diferido según la reunión; no bloquea el recorrido actual"/><Pending>Equivalente de circulación y factor de fricción no están validados. No se muestran valores simulados como datos del cliente.</Pending></section></>}

function reportsOf(data:RecoveredData):OperationalReport[]{return (data as RecoveredData & {reports?:OperationalReport[]}).reports??[];}
function DiameterSummary({data}:{data:RecoveredData}){const groups=["H","N","P","Sin clasificar"];const classify=(s:OperationalShift)=>{const text=s.diameter?.trim().toUpperCase();return text&&/^(HQ|NQ|PQ)(?:\b|\s|\()/u.test(text)?text[0]:"Sin clasificar";};return <section className="panel supplementary-panel table-panel"><Head title="Avance por diámetro declarado" subtitle="HQ → H · NQ → N · PQ → P · lo no declarado no se reparte proporcionalmente"/><table><thead><tr><th>Grupo</th><th>Posiciones</th><th>Metros conocidos</th><th>Avances ausentes</th></tr></thead><tbody>{groups.map(group=>{const rows=data.shifts.filter(s=>classify(s)===group);return <tr key={group}><td>{group}</td><td>{rows.length}</td><td>{fmt(sumKnown(rows.map(s=>s.advanceM)),2)} m</td><td>{rows.filter(s=>s.advanceM===null).length}</td></tr>})}</tbody></table></section>}
function ConsumptionSummary({data}:{data:RecoveredData}){const totals=new Map<string,number>();for(const report of reportsOf(data))for(const m of report.consumptions)if(m.validity==="observed"&&m.value!==null&&m.value>=0){const key=`${m.label} · ${m.unit??"unidad sin confirmar"}`;totals.set(key,(totals.get(key)??0)+m.value);}return <section className="panel supplementary-panel"><Head title="Agua y combustible observados" subtitle="Total de lecturas válidas por concepto y unidad · sin duplicar el reporte entre guardias" action="Ver consumos" actionHref={contextHref(data,"/consumibles")}/><div className="parameters-grid">{[...totals].map(([label,value])=><div className="metric-range" key={label}><header><Droplets/><span>{label}</span><b>{fmt(value,3)}</b></header><small>Unidad de origen; gls no convertido a litros</small></div>)}</div>{totals.size===0&&<Pending>Sin cantidades válidas importadas en este filtro.</Pending>}</section>}
function ReportObservations({data,kind}:{data:RecoveredData;kind:"equipmentHours"|"fluidParameters"}){const [label,setLabel]=useState("");const observations=reportsOf(data).flatMap(report=>report[kind].map(m=>({...m,report})));const labels=[...new Set(observations.map(m=>m.label))];const selected=label||labels[0]||"";return <section className="panel supplementary-panel table-panel"><Head title={kind==="equipmentHours"?"Horas de equipo reportadas":"Parámetros de fluido reportados"} subtitle={kind==="equipmentHours"?"Lecturas de equipo y sus celdas de origen; no horas de guardia × 12 ni una suma de horómetros":"Observaciones del reporte con unidades originales; sin calibraciones inferidas"}/><div className="actionbar"><label>Concepto<select aria-label={kind==="equipmentHours"?"Concepto de horas de equipo":"Parámetro de fluido"} value={selected} onChange={e=>setLabel(e.target.value)}>{labels.map(v=><option key={v}>{v}</option>)}{labels.length===0&&<option value="">No incorporado</option>}</select></label><span>{observations.length} observaciones conservadas</span></div>{observations.length===0?<Pending>Este contexto no contiene lecturas incorporadas. No se sustituyen por la duración teórica de una guardia.</Pending>:<details><summary style={{padding:16}}>Ver observaciones de {selected} y fiscalizar celdas</summary><table><thead><tr><th>Fecha / equipo</th><th>Guardia</th><th>Observación</th><th>Unidad</th><th>Calidad</th><th>Origen</th></tr></thead><tbody>{observations.filter(m=>m.label===selected).map(m=><tr key={`${m.report.key}|${m.key}`}><td>{m.report.date} · {m.report.rigCode}</td><td>{m.shiftType===null?"Reporte":m.shiftType==="day"?"Día":"Noche"}</td><td>{fmt(m.value,3)}</td><td>{m.unit??"Sin confirmar"}</td><td>{m.validity==="observed"?"Observado":m.validity==="invalid"?"Inválido · revisar":"Ausente"}</td><td>{m.report.source.file} · {m.report.source.sheet}<details><summary>Celdas e incidencias</summary>{Object.values(m.cells).map(c=>`${c.cell}: ${c.raw??"vacío"}`).join(" · ")}<p>{m.warnings.join(" · ")}</p></details></td></tr>)}</tbody></table></details>}</section>}
function RecoveredInventory({data}:ViewProps){const history=reconstructCrownHistory(data.crowns,data.shifts);return <><div className="inventory-overview"><div><PackageSearch/><span><b>—</b>unidades físicas sin conteo</span></div><div><CheckCircle2/><span><b>—</b>disponibilidad no confirmada</span></div><div className="warn"><AlertTriangle/><span><b>—</b>reposición no declarada</span></div></div><section className="panel table-panel"><Head title="Inventario de coronas" subtitle="Identidades observadas; existencias por confirmar"/><table><thead><tr><th>Serie</th><th>Marca / tipo</th><th>Stock</th><th>Reservado</th><th>Disponible</th><th>Estado</th></tr></thead><tbody>{history.runs.map(r=><tr key={r.id}><td>{r.serial??"Identidad incompleta"}</td><td>{r.brand??"No informada"} · {r.type??"No informado"}</td><td>—</td><td>—</td><td>—</td><td><span className="status warning">REQUIERE CONTEO</span></td></tr>)}</tbody></table></section><section className="panel supplementary-panel"><Head title="Almacén de insumos" subtitle="No convertir consumo en existencia"/><Pending>Los consumibles observados están en Consumos. Faltan saldo inicial, entradas y salidas confirmadas para calcular stock.</Pending><Link className="button-link" href={contextHref(data,"/consumibles")}>Ver consumos <ChevronRight/></Link></section></>}
function RecoveredConsumables({data}:ViewProps){const [group,setGroup]=useState("all"),[page,setPage]=useState(1),[showTotals,setShowTotals]=useState(false);const observations=reportsOf(data).flatMap(report=>[...report.consumptions,...report.materials].map(m=>({...m,report})));const filtered=observations.filter(m=>group==="all"||m.label===group);const currentPage=Math.min(page,Math.max(1,Math.ceil(filtered.length/24)));const totals=new Map<string,number>();for(const m of filtered)if(m.validity==="observed"&&m.value!==null&&m.value>=0){const key=`${m.label} (${m.unit??"unidad no confirmada"})`;totals.set(key,(totals.get(key)??0)+m.value);}return <><div className="kpi-grid four"><Kpi label="Lecturas observadas" value={String(observations.filter(m=>m.validity==="observed").length)} icon={Droplets} sub="No suma cantidades de unidades distintas"/><Kpi label="Lecturas a revisar" value={String(observations.filter(m=>m.validity==="invalid").length)} icon={AlertTriangle} tone="amber"/><Kpi label="Reportes con consumos" value={String(new Set(observations.map(m=>m.report.key)).size)} icon={ClipboardCheck} tone="blue"/><Kpi label="Costo por metro" value="—" sub="Requiere tarifas de esta campaña" tone="purple"/></div><div className="actionbar"><label>Insumo<select value={group} onChange={e=>{setGroup(e.target.value);setPage(1);}}><option value="all">Todos los insumos</option>{[...new Set(observations.map(m=>m.label))].map(label=><option key={label}>{label}</option>)}</select></label><span>Unidades originales · gls no se convierte a litros</span></div><div className="consumables-panels"><section className="panel"><Head title="Consumos observados" subtitle="Totales separados por ítem y unidad, sólo lecturas válidas"/>{group==="all"||new Set(filtered.filter(m=>m.validity==="observed").map(m=>m.unit)).size>1?<Pending>Selecciona un insumo con una sola unidad para graficarlo. La cobertura inferior mantiene cada concepto y unidad separados; no se comparan unidades distintas en un mismo eje.</Pending>:<EChart className="chart chart-lg" ariaLabel="Consumos por ítem con unidad original" option={cartesian([...totals.keys()],[{name:"Cantidad observada",values:[...totals.values()],color:"#41d6a3"}],"unidad indicada")}/>}</section><section className="panel"><Head title="Cobertura y calidad" subtitle="No se duplican cantidades de reporte entre día y noche"/><div className="crown-ranking">{[...totals].slice(0,showTotals?undefined:8).map(([label,value])=><div key={label}><Droplets/><div><b>{label}</b><small>Conserva granularidad reportada</small></div><strong>{fmt(value,3)}</strong></div>)}</div>{totals.size>8&&<button className="button-link" onClick={()=>setShowTotals(!showTotals)}>{showTotals?"Ver ocho conceptos":`Ver los ${totals.size} conceptos con su unidad`}</button>}{totals.size===0&&<Pending>Existen bloques en la fuente; faltan lecturas válidas incorporadas en este filtro.</Pending>}</section></div><section className="panel table-panel"><table><thead><tr><th>Fecha / equipo</th><th>Insumo</th><th>Guardia</th><th>Cantidad</th><th>Unidad</th><th>Estado</th><th>Origen</th></tr></thead><tbody>{filtered.slice((currentPage-1)*24,currentPage*24).map(m=><tr key={`${m.report.key}|${m.key}`}><td>{m.report.date} · {m.report.rigCode}</td><td>{m.label}</td><td>{m.shiftType===null?"Reporte completo":m.shiftType==="day"?"Día":"Noche"}</td><td>{fmt(m.value,3)}</td><td>{m.unit??"Sin confirmar"}</td><td><span className={`status ${m.validity==="observed"?"success":"warning"}`}>{m.validity==="observed"?"OBSERVADO":m.validity==="invalid"?"INVÁLIDO · EXCLUIDO":"NO REGISTRADO"}</span></td><td><details><summary>{m.report.source.file} · {m.report.source.sheet}</summary>{Object.values(m.cells).map(c=>`${c.cell}: ${c.raw??"vacío"}`).join(" · ")}<p>{m.warnings.join(" · ")}</p></details></td></tr>)}</tbody></table><Pagination page={currentPage} total={filtered.length} size={24} onPage={setPage}/></section><section className="panel supplementary-panel"><Head title="Costo normalizado por metro" subtitle="Hipótesis y costos reales deben mantenerse separados"/><Pending>No hay tarifas autorizadas. No se incorporan los precios de marzo de otra campaña al reporte actual.</Pending></section></>}
function RecoveredAnalytics({data}:ViewProps){const days=[...new Set(data.shifts.map(s=>s.date))].sort();const utilization=days.map(date=>{const rows=data.shifts.filter(s=>s.date===date&&s.drillingHours!==null&&s.totalHours!==null);const result=ratio(sumKnown(rows.map(s=>s.drillingHours)),sumKnown(rows.map(s=>s.totalHours)));return result===null?null:result*100;});const history=compareCrownHistory(reconstructCrownHistory(data.crowns,data.shifts));const radar={tooltip:{},radar:{indicator:[{name:"ROP",max:5},{name:"Bajo costo",max:5},{name:"Vida",max:5},{name:"Disponibilidad",max:5},{name:"Evidencia",max:5}],splitLine:{lineStyle:{color:"#334048"}},splitArea:{areaStyle:{color:["transparent"]}},axisName:{color:"#a1adb4"}},series:[{type:"radar",data:[]}]};const util={tooltip:{trigger:"axis"},grid:{left:44,right:20,top:24,bottom:35},xAxis:{type:"category",data:days,axisLabel:{color:"#78858d",hideOverlap:true}},yAxis:{type:"value",min:0,max:100,axisLabel:{color:"#78858d",formatter:"{value}%"},splitLine:{lineStyle:{color:"#263039"}}},series:[{name:"Utilización pareada",type:"line",data:utilization,smooth:false,connectNulls:false,areaStyle:{color:"rgba(65,214,163,.12)"},lineStyle:{color:"#41d6a3",width:3},itemStyle:{color:"#41d6a3"}}]};return <><div className="split-grid"><section className="panel"><Head title="Perfil comparativo de coronas" subtitle="ROP, costo, vida, stock y evidencia · no se completan ausencias con cero"/><EChart option={radar} className="chart chart-lg" ariaLabel="Perfil de comparación pendiente de costo, vida y disponibilidad"/><Pending>Faltan costo, vida y stock comparables para trazar el perfil normalizado. La ROP observada se consulta en Coronas, sin un puntaje artificial.</Pending></section><section className="panel"><Head title="Tendencia de utilización" subtitle="Horas de perforación / horas registradas en las mismas posiciones; meta no declarada"/><EChart option={util} className="chart chart-lg" ariaLabel="Utilización diaria de turnos con horas pareadas"/></section></div><section className="panel"><Head title="Lecturas clave" subtitle="Señales calculadas del contexto, sin causalidad inferida"/><div className="insight-cards"><div><Gauge/><b>{fmt(data.summary.ropMPerHour,3)} m/h de ROP pareada</b><p>{data.summary.ropCoverage} posiciones con avance y horas compatibles.</p></div><div><PackageSearch/><b>{history.length} grupos de marca / tipo observados</b><p>La comparación descriptiva no confirma stock, régimen ni compatibilidad.</p></div><div><AlertTriangle/><b>Cobertura explícita</b><p>{data.summary.missingAdvance} avances y {data.summary.missingHours} horas ausentes. No se interpretan como ceros.</p></div></div></section><DiameterSummary data={data}/><section className="panel supplementary-panel"><Head title="Pozo anterior vs actual" subtitle="Comparación de tiempo, costo y ROP; requiere contexto comparable confirmado"/><div className="parameters-grid"><div className="metric-range"><header><i style={{background:"#56c7ff"}}/><span>Tiempo transcurrido comparable</span><b>—</b></header><small>Falta seleccionar campaña anterior compatible</small></div><div className="metric-range"><header><i style={{background:"#56c7ff"}}/><span>Costo operativo</span><b>—</b></header><small>Tarifa de campaña no registrada</small></div><div className="metric-range"><header><i style={{background:"#56c7ff"}}/><span>ROP del contexto actual</span><b>{fmt(data.summary.ropMPerHour,3)} m/h</b></header><small>Sin cambio porcentual frente a otra campaña</small></div></div></section></>}
function RecoveredImports({session,reload}:ViewProps){return <RecoveredImportPanel session={session} onReload={reload}/>}
function RecoveredAssistant({data,session}:ViewProps){return <PrivateAssistant key={JSON.stringify(data.filters)} data={data} session={session}/>}
function RecoveredReport({data,session}:ViewProps){const activity=activities(data.shifts),maxHours=Math.max(1,...activity.map(a=>a[1])),history=compareCrownHistory(reconstructCrownHistory(data.crowns,data.shifts));return <><section className="report-page panel"><div className="report-actions"><span className="status success">CONTEXTO FILTRADO</span><button onClick={()=>window.print()}><Printer/>Imprimir / Guardar PDF</button></div><header className="report-header"><div className="side-brand"><span className="brand-mark"><Gauge/></span><span>DRILLOPS <b>INTELLIGENCE</b></span></div><div><small>REPORTE EJECUTIVO DE SONDEO</small><h2>{data.summary.holes.join(", ")||"Sondeo no informado"}</h2><p>Periodo: {data.shifts[0]?.date??"Sin fecha"} — {data.shifts.at(-1)?.date??"Sin fecha"} · {session.tenantName??"Empresa autorizada"}</p></div></header><div className="report-kpis"><div><span>Metros perforados</span><b>{fmt(data.summary.advanceM)} m</b><small>{fmt(data.summary.drillingHours)} h de perforación registradas</small></div><div><span>ROP ponderado</span><b>{fmt(data.summary.ropMPerHour,3)} m/h</b><small>{data.summary.ropCoverage} turnos pareados</small></div><div><span>Posiciones de turno</span><b>{data.summary.shiftCount}</b><small>Incluye avances cero explícitos</small></div><div><span>Costo operativo estimado</span><b>—</b><small>Requiere tarifa autorizada</small></div></div><div className="report-columns"><section><h3>Resumen operacional</h3><p>{data.summary.missingAdvance} avances y {data.summary.missingHours} horas no registrados; las ausencias no se convierten en cero. Objetivos y tarifas pendientes. No se infiere geología ni desgaste de una media de turno.</p><h3>Horas por actividad · sin clasificación automática NPT</h3>{activity.slice(0,8).map(([label,hours])=><div className="report-bar" key={label}><span>{label}</span><i><b style={{width:`${hours/maxHours*100}%`}}/></i><strong>{fmt(hours)} h</strong></div>)}</section><section><h3>Rendimiento de coronas</h3><table><thead><tr><th>Marca / tipo</th><th>ROP</th><th>Atribuibles</th></tr></thead><tbody>{history.map(r=><tr key={`${r.brand}|${r.type}`}><td>{r.brand??"No informada"} · {r.type??"No informado"}</td><td>{fmt(r.ropMPerHour,3)}</td><td>{fmt(r.attributedMetresM)} m</td></tr>)}</tbody></table><h3>Revisión operacional</h3><div className="report-rec"><Sparkles/><p><b>Decisión humana con evidencia</b><br/>La comparación histórica no determina desgaste, stock, vida restante ni compatibilidad. Revisa el candidato y sus límites en Bit Advisor.</p></div></section></div><RecoveredDecisionEvidence data={data}/><footer>Generado por DrillOps Intelligence · Fuente: registros autorizados PostgreSQL · contexto filtrado</footer></section><section className="panel supplementary-panel"><Head title="Adjuntos del reporte" subtitle="Evidencia documental del contexto"/><Pending>No hay adjuntos incorporados al reporte. La carga de adjuntos está pendiente; no se muestran imágenes de ejemplo.</Pending></section><ShiftEvidence shifts={data.shifts}/></>}
function RecoveredSettings({session}:ViewProps){const [tab,setTab]=useState("General");const tabs=["General","Usuarios y roles","Accesos por plan","IA y privacidad","Auditoría"];return <div className="settings-grid"><nav>{tabs.map(t=><button key={t} className={tab===t?"active":""} onClick={()=>setTab(t)}>{t}</button>)}</nav><section className="panel settings-form"><h3>{tab}</h3>{tab==="General"?<><p>Identidad y contexto de la sesión actual.</p><label>Empresa<input readOnly value={session.tenantName??session.tenantId}/></label><label>Cuenta<input readOnly value={session.email}/></label><label>Perfil efectivo<input readOnly value={session.role}/></label><p>Turnos históricos de 12 h; offline y sincronización permanecen diferidos.</p></>:tab==="Usuarios y roles"?<><div className="settings-list"><div><ShieldCheck/><span><b>{session.name}</b><small>{session.role} · cuenta individual</small></span><span className="status success">SESIÓN ACTUAL</span></div></div><Pending>No se muestra un listado inventado de usuarios. La administración de membresías no está disponible en esta pantalla.</Pending></>:tab==="Accesos por plan"?<><p>Plan actual: {session.plan}</p><p>Los permisos efectivos se validan en servidor. No se ofrece cambio de plan ni se alteran cobros desde este candidato.</p></>:tab==="IA y privacidad"?<><div className="privacy-card"><ShieldCheck/><div><b>Consultas de sólo lectura</b><span>Drill Assistant determinístico sobre la empresa de la sesión.</span></div></div><div className="privacy-card"><Database/><div><b>Sin mezcla de empresas</b><span>El servidor y la persistencia mantienen el perímetro del tenant.</span></div></div></>:<Pending>La evidencia persistida de decisiones se consulta en Bit Advisor y Reportes. No se inventan eventos administrativos.</Pending>}</section></div>}
function RecoveredSurvey({data}:ViewProps){const [key,setKey]=useState(""),[page,setPage]=useState(1);const reports=reportsOf(data);const contexts=[...new Set(reports.filter(r=>r.survey.length).map(r=>`${r.rigCode} · ${r.holeCode??"Sin sondeo"}`))];const active=key||contexts[0]||"";const stations=reports.filter(r=>`${r.rigCode} · ${r.holeCode??"Sin sondeo"}`===active).flatMap(r=>r.survey.map(s=>({...s,report:r})));const currentPage=Math.min(page,Math.max(1,Math.ceil(stations.length/24)));const observed=stations.filter(s=>s.valid&&s.depthM!==null&&s.dip!==null&&s.azimuth!==null);const unique=[...new Map(observed.map(s=>[`${s.depthM}|${s.dip}|${s.azimuth}`,s])).values()].sort((a,b)=>a.depthM!-b.depthM!);return <><div className="actionbar survey-actions"><label>Sondeo<select aria-label="Sondeo de survey" value={active} onChange={e=>{setKey(e.target.value);setPage(1);}}>{contexts.map(c=><option key={c}>{c}</option>)}{contexts.length===0&&<option value="">Sin estaciones importadas</option>}</select></label><span className="status success">{unique.length} observaciones distintas</span><div className="view-switch"><button className="active">Perfiles 2D</button><button disabled title="Requiere convención de DIP, referencia y método validados">Trayectoria 3D pendiente</button></div></div><section className="panel survey-visual"><Head title="Survey direccional" subtitle="DIP y azimut observados por profundidad · no se supone norte verdadero"/><EChart className="chart survey-chart" ariaLabel="DIP y azimut observados por profundidad" option={{tooltip:{trigger:"item"},grid:[{left:60,right:"54%",top:30,bottom:50},{left:"58%",right:30,top:30,bottom:50}],xAxis:[{type:"value",name:"DIP °",axisLabel:{color:"#89949d"}},{type:"value",gridIndex:1,name:"Azimut °",axisLabel:{color:"#89949d"}}],yAxis:[{type:"value",inverse:true,name:"Profundidad m",axisLabel:{color:"#89949d"}},{type:"value",gridIndex:1,inverse:true,axisLabel:{color:"#89949d"}}],series:[{type:"scatter",data:unique.map(s=>[s.dip,s.depthM]),itemStyle:{color:"#56c7ff"}},{type:"scatter",xAxisIndex:1,yAxisIndex:1,data:unique.map(s=>[s.azimuth,s.depthM]),itemStyle:{color:"#d7ff43"}}]}}/>{!unique.length&&<Pending>Las estaciones existen en el Excel; este contexto no tiene estaciones válidas incorporadas. No se dibuja una trayectoria ficticia.</Pending>}</section><section className="panel table-panel"><table><thead><tr><th>Profundidad</th><th>DIP</th><th>Azimut</th><th>Referencia / equipo</th><th>Origen</th><th>Estado</th></tr></thead><tbody>{stations.slice((currentPage-1)*24,currentPage*24).map(s=><tr key={`${s.report.key}|${s.key}`}><td>{fmt(s.depthM)} m</td><td>{fmt(s.dip,2)}°</td><td>{fmt(s.azimuth,2)}°</td><td>{s.reference??"No informada"} / {s.equipment??"No informado"}</td><td>{s.report.source.file} · {s.report.source.sheet}<details><summary>Celdas</summary>{Object.values(s.cells).map(c=>`${c.cell}: ${c.raw??"vacío"}`).join(" · ")}</details></td><td>{s.valid?"Observación válida":"Revisar fuente"}</td></tr>)}</tbody></table><Pagination page={currentPage} total={stations.length} size={24} onPage={setPage}/></section><section className="panel supplementary-panel"><Head title="Proyección de trayectoria" subtitle="El visor 3D permanece condicionado a referencias válidas"/><Pending>Falta confirmar convención angular, referencia del azimut, origen y método. Las observaciones 2D no se interpolan ni se convierten a coordenadas geográficas.</Pending></section></>}
function RecoveredDepth({data}:ViewProps){const [hole,setHole]=useState(data.summary.holes[0]??"");const [visible,setVisible]=useState({rop:true,pressure:true,torque:true,rpm:true,recovery:true,mse:true,hardness:true});const rows=data.shifts.filter(s=>s.holeCode===hole&&s.startDepthM!==null&&s.endDepthM!==null);const tracks=["rop","pressure","torque","rpm","recovery","mse","hardness"] as const;const labels={rop:"ROP",pressure:"Pulldown",torque:"Torque",rpm:"RPM",recovery:"Recup.",mse:"MSE",hardness:"Mohs"},units={rop:"m/h",pressure:"PSI",torque:"unidad pendiente",rpm:"rpm",recovery:"% no registrado",mse:"requiere parámetros",hardness:"no declarado"};const active=tracks.filter(t=>visible[t]);const value=(s:OperationalShift,t:typeof tracks[number])=>t==="rop"?ratio(s.advanceM,s.drillingHours):t==="pressure"?s.parameters.pulldownPsi:t==="torque"?s.parameters.torque:t==="rpm"?s.parameters.rpm:null;const option={animation:false,tooltip:{trigger:"item"},title:active.map((t,i)=>({text:labels[t],subtext:units[t],left:`${3+i*94/active.length}%`,top:4,textStyle:{fontSize:12,color:"#eef3f5"},subtextStyle:{fontSize:9,color:"#7f8c94"}})),grid:active.map((_,i)=>({left:`${3+i*94/active.length}%`,width:`${88/active.length}%`,top:55,bottom:30,containLabel:i===0})),xAxis:active.map((_,i)=>({type:"value",gridIndex:i,position:"top",splitNumber:2,axisLabel:{color:"#78868e",fontSize:8,hideOverlap:true}})),yAxis:active.map((_,i)=>({type:"value",gridIndex:i,inverse:true,min:rows.length?Math.min(...rows.map(s=>s.startDepthM!)):0,max:rows.length?Math.max(...rows.map(s=>s.endDepthM!)):1,axisLabel:{show:i===0,color:"#91a0a8"},splitLine:{lineStyle:{color:"#263139",type:"dashed"}}})),dataZoom:[{type:"inside",yAxisIndex:active.map((_,i)=>i),filterMode:"none"},{type:"slider",yAxisIndex:active.map((_,i)=>i),right:4,width:12,filterMode:"none"}],series:active.flatMap((t,i)=>rows.filter(s=>value(s,t)!==null).map(s=>({name:`${s.date} ${s.shiftType} · rango de turno`,type:"line",xAxisIndex:i,yAxisIndex:i,showSymbol:true,symbolSize:3,lineStyle:{color:colors[i%colors.length],width:2},itemStyle:{color:colors[i%colors.length]},data:[[value(s,t),s.startDepthM],[value(s,t),s.endDepthM]]})))};return <><div className="depth-toolbar"><div><label>Sondeo<select aria-label="Sondeo de profundidad" value={hole} onChange={e=>setHole(e.target.value)}>{data.summary.holes.map(h=><option key={h}>{h}</option>)}</select></label><span>Rangos de turno · sin sensores ficticios</span></div><div className="legend-inline"><span><i className="event-line"/>Rango observado</span></div></div><div className="depth-summary"><div><b>{rows.length}</b><span>rangos de turno</span></div><div><b>—</b><span>MSE: parámetros pendientes</span></div><div><b>—</b><span>recuperación no registrada</span></div><div><b>{data.crowns.filter(c=>c.holeCode===hole).length}</b><span>instantáneas de corona, no corridas</span></div></div><section className="depth-layout"><aside className="track-panel"><h3>Pistas</h3><p>Variables observadas en su rango, no interpoladas.</p>{tracks.map(t=><label key={t}><input type="checkbox" checked={visible[t]} onChange={()=>setVisible({...visible,[t]:!visible[t]})}/><i className={`track-color ${t}`}/><span>{labels[t]}<small>{units[t]}</small></span></label>)}<hr/><div className="source-note"><ShieldCheck/><div><b>Fuente de datos</b><span>Reportes agregados por turno</span></div></div></aside><section className="panel depth-chart-panel"><div className="depth-ruler-note">PROFUNDIDAD ↓</div>{active.length?<EChart className="depth-chart" option={option} ariaLabel="Pistas operacionales con rangos de profundidad de turno"/>:<Pending>Activa al menos una pista.</Pending>}</section><aside className="depth-events"><h3>Observaciones de corona</h3>{data.crowns.filter(c=>c.holeCode===hole).slice(-10).map(c=><div key={`${c.key}|${c.date}`}><i/><small>{fmt(c.startDepthM)} – {fmt(c.endDepthM)} m</small><b>{c.serial??"Serie no informada"}</b><span>{c.date} · instantánea, no cambio confirmado</span></div>)}</aside></section><div className="depth-insight"><Sparkles/><div><b>Lectura operacional por profundidad</b><p>Una media de turno se muestra en su rango de profundidad. No representa mediciones cada 3 m ni confirma litología, desgaste o una anomalía puntual.</p></div><Link href={contextHref(data,"/bit-advisor")}>Abrir Bit Advisor <ChevronRight/></Link></div><ShiftEvidence shifts={data.shifts.filter(s=>s.holeCode===hole)}/></>}
